'use strict';
let fundingView='orders',leaderboardView='all';
function seedOrders(){return [
 {id:'O-3101',itemId:'F-1046',title:'Rice and grains for three communities',buyer:'Central Ohio Food Share',buyerType:'Food bank',supplier:'Heartland Grain Supply',quantity:10,unit:'pallets',unitPrice:420,deliveryTarget:650,deadline:'2026-10-29',status:'Open',notes:'A shared food purchase. Supplier availability, allocations and the final delivery quote still need confirmation.',pledges:[{id:'op1',sponsor:'Northline Manufacturing',food:1200,delivery:0,status:'Confirmed'},{id:'op2',sponsor:'Oak & Field Team',food:300,delivery:0,status:'Pending'}]},
 {id:'O-3102',itemId:'',title:'Grocery boxes for a neighborhood pantry',buyer:'Community Pantry Volunteers',buyerType:'Community group / individual',supplier:'Market Street Wholesale',quantity:100,unit:'boxes',unitPrice:18,deliveryTarget:0,deadline:'2026-10-30',status:'Open',notes:'Volunteers are purchasing grocery boxes for local distribution. Pickup is arranged, so no transportation funding is requested.',pledges:[{id:'op3',sponsor:'Riverbend Neighbors',food:500,delivery:0,status:'Confirmed'}]}
];}
state.orders??=seedOrders();
state.generalDonations??=[];
const seedWithMessages=seed;seed=()=>({...seedWithMessages(),orders:seedOrders(),generalDonations:[]});
const order=id=>state.orders.find(o=>o.id===id);
const orderTarget=(o,bucket)=>bucket==='food'?round(o.quantity*o.unitPrice):o.deliveryShipmentId&&ship(o.deliveryShipmentId)?target(ship(o.deliveryShipmentId)):round(o.deliveryTarget);
const orderSum=(o,bucket,status)=>round(o.pledges.filter(p=>p.status===status).reduce((n,p)=>n+(Number(p[bucket])||0),0)+(bucket==='delivery'&&o.deliveryShipmentId?(ship(o.deliveryShipmentId)?.pledges||[]).filter(p=>p.status===status).reduce((n,p)=>n+p.amount,0):0));
const orderGap=(o,bucket)=>Math.max(0,round(orderTarget(o,bucket)-orderSum(o,bucket,'Confirmed')-orderSum(o,bucket,'Pending')));
const orderOpen=o=>!!o&&o.status!=='Canceled'&&(!o.deliveryShipmentId||!['Canceled','Delivered','In transit'].includes(ship(o.deliveryShipmentId)?.status))&&o.deadline>=demoDate&&(!o.itemId||!!item(o.itemId)&&openFood(item(o.itemId))&&item(o.itemId).price>0);
const orderFunded=o=>['food','delivery'].every(b=>orderSum(o,b,'Confirmed')>=orderTarget(o,b));
function orderStatus(o){return o.deliveryShipmentId&&ship(o.deliveryShipmentId)?.status==='Delivered'?badge('Delivered','teal'):o.deliveryShipmentId&&ship(o.deliveryShipmentId)?.status==='In transit'?badge('In transit','blue'):o.status==='Canceled'?badge('Canceled','gray'):!orderOpen(o)?badge('Review needed','amber'):orderFunded(o)?badge('Funding confirmed','teal'):orderGap(o,'food')+orderGap(o,'delivery')===0?badge('Awaiting confirmation','blue'):badge('Funding open','amber');}
function addOrderPledge(id,sponsor,food,delivery){const o=order(id);food=round(Number(food));delivery=round(Number(delivery));sponsor=String(sponsor||'').trim();if(!orderOpen(o))throw Error('This order is unavailable or needs review.');if(!sponsor)throw Error('Enter a sponsor name.');if(!Number.isFinite(food)||!Number.isFinite(delivery)||food<0||delivery<0||food+delivery<=0)throw Error('Enter a positive food or transportation contribution.');if(food>orderGap(o,'food')||delivery>orderGap(o,'delivery'))throw Error('A contribution exceeds the remaining amount for that purpose.');const p={id:uid('op'),sponsor:sponsor.slice(0,80),food,delivery,status:'Pending'};o.pledges.push(p);return p;}
function confirmOrderPledge(id,pid){if(!ops())throw Error('Switch to BHD Operations to confirm funding.');const o=order(id),p=o?.pledges.find(p=>p.id===pid);if(!orderOpen(o)||!p||p.status!=='Pending')throw Error('This pledge is unavailable for confirmation.');for(const b of ['food','delivery'])if(orderSum(o,b,'Confirmed')+p[b]>orderTarget(o,b))throw Error('Reconcile this pledge with the order budget first.');p.status='Confirmed';}
function createPurchaseOrder(input){const text=n=>String(input[n]||'').trim(),quantity=Number(input.quantity),unitPrice=round(Number(input.unitPrice)),deliveryTarget=round(Number(input.deliveryTarget));for(const n of ['title','buyer','supplier','deadline'])if(!text(n))throw Error('Complete the order, purchaser, supplier and deadline.');if(!Number.isInteger(quantity)||quantity<1||!Number.isFinite(unitPrice)||unitPrice<=0||!Number.isFinite(quantity*unitPrice)||!Number.isFinite(deliveryTarget)||deliveryTarget<0)throw Error('Use a positive whole quantity and food price; transportation may be zero.');if(text('deadline')<demoDate)throw Error('Choose a deadline on or after the demonstration date.');if(!['pallets','cases','boxes','orders'].includes(input.unit))throw Error('Choose a valid order unit.');if(!['Food bank','Community group / individual'].includes(input.buyerType))throw Error('Choose a purchaser type.');if(input.itemId){const f=item(input.itemId);if(!f||!openFood(f)||!['For sale','Shared order'].includes(f.type)||f.price<=0)throw Error('Choose an available food purchase listing.');if(state.orders.some(o=>o.itemId===f.id&&o.status!=='Canceled'))throw Error('This listing already has an order campaign.');if(quantity>f.pallets-held(f)||unitPrice!==f.price||input.unit!=='pallets')throw Error('The quantity or price no longer matches the listing.');}const o={id:uid('O'),itemId:input.itemId||'',title:text('title').slice(0,100),buyer:text('buyer').slice(0,100),buyerType:input.buyerType,supplier:text('supplier').slice(0,100),quantity,unit:input.unit,unitPrice,deliveryTarget,deadline:text('deadline'),status:'Open',notes:text('notes').slice(0,1000),pledges:[]};state.orders.unshift(o);return o;}
function fundingTabs(){return '<div class="funding-tabs" role="group" aria-label="Funding options">'+[['orders','box','Fund the order'],['deliveries','truck','Sponsor a delivery'],['general','heart','General donations']].map(([v,i,t])=>'<button class="funding-tab '+(fundingView===v?'active':'')+'" data-action="funding-view" data-id="'+v+'" aria-pressed="'+(fundingView===v)+'">'+icon(i)+t+'</button>').join('')+'</div>';}
function sponsorPage(){return fundingTabs()+(fundingView==='general'?generalDonationPage():fundingView==='orders'?orderFundingPage():deliveryFundingPage());}
function orderBudget(o,b){const target=orderTarget(o,b),confirmed=orderSum(o,b,'Confirmed'),pending=orderSum(o,b,'Pending'),gap=orderGap(o,b);return '<section class="order-budget"><div class="row budget-title"><strong>'+icon(b==='food'?'box':'truck')+' '+(b==='food'?'Food purchase':'Transportation')+'</strong><strong>'+money(target)+'</strong></div>'+(target?'<div class="progress"><span style="width:'+Math.min(100,confirmed/target*100)+'%"></span><span class="pending" style="width:'+Math.min(100-confirmed/target*100,pending/target*100)+'%"></span></div><div class="progress-label"><span>'+money(confirmed)+' confirmed · '+money(pending)+' pending</span><strong>'+money(gap)+' open</strong></div>':'<p class="small muted">Pickup arranged / no transportation funding requested.</p>')+'</section>';}
function orderFundingPage(){const active=state.orders.filter(orderOpen),sum=(b,s)=>active.reduce((n,o)=>n+orderSum(o,b,s),0);return head('','Fund the order','Some food is donated. Some has to be purchased. Help a food bank, individual or community group cover the food, the delivery, or both.',btn(icon('plus')+' Start an order campaign','order-create','primary'))+'<div class="snapshot sponsor-stats">'+snapshotCell('Orders seeking support',active.filter(o=>!orderFunded(o)).length,'food banks and community purchasers','sponsor')+snapshotCell('Food purchases still needed',money(active.reduce((n,o)=>n+orderGap(o,'food'),0)),'available for new food pledges','sponsor','amber-text')+snapshotCell('Transportation still needed',money(active.reduce((n,o)=>n+orderGap(o,'delivery'),0)),'for these food orders','sponsor')+snapshotCell('Confirmed order funding',money(sum('food','Confirmed')+sum('delivery','Confirmed')),'food and transportation combined','sponsor','teal-text')+'</div><div class="section-head"><span class="small muted">Purchase campaigns · illustrative quotes</span>'+btn('See the funding leaderboard '+icon('arrow'),'quick','ghost','impact')+'</div><div class="sponsor-grid">'+state.orders.map(o=>'<article class="sponsor-card order-card"><div class="sponsor-top"><span class="small muted">'+o.id+' · '+esc(o.buyerType)+'</span>'+orderStatus(o)+'</div><h3>'+esc(o.title)+'</h3><p>Purchased by <strong>'+esc(o.buyer)+'</strong><br>Supplier: '+esc(o.supplier)+'</p><div class="order-quantity">'+num(o.quantity)+' '+esc(o.unit)+' × '+money(o.unitPrice)+' each <span>Funding deadline '+date(o.deadline)+'</span></div>'+orderBudget(o,'food')+orderBudget(o,'delivery')+'<div class="note">Food support is assigned to this purchase. Transportation support stays separate. Funding does not place the order or reserve inventory.</div><div class="sponsor-actions">'+(orderOpen(o)&&orderGap(o,'food')+orderGap(o,'delivery')>0?btn('Fund the order '+icon('arrow'),'order-pledge','primary',o.id):'')+btn('Details & pledges','order-detail','',o.id)+'</div></article>').join('')+'</div><div class="note blue">Demonstration only. Contributions are simulated and require operations confirmation. A funded order does not count as delivered food. No payments are collected.</div>';}
function orderForm(kind,body,id,label){return '<form data-funding-form="'+kind+'" data-id="'+esc(id||'')+'">'+body+'<div class="error" role="alert"></div><button class="btn primary full" type="submit">'+label+'</button></form>';}
function orderDetail(id){const o=order(id);if(!o)return;dialog(o.title,orderStatus(o)+'<p class="muted" style="margin-top:14px">Purchased by '+esc(o.buyer)+' · '+esc(o.buyerType)+'</p><div class="details">'+detail('Food supplier',o.supplier)+detail('Food quantity',num(o.quantity)+' '+o.unit+' × '+money(o.unitPrice))+detail('Food purchase budget',money(orderTarget(o,'food')))+detail('Transportation budget',money(orderTarget(o,'delivery')))+detail('Combined order budget',money(orderTarget(o,'food')+orderTarget(o,'delivery')))+detail('Funding deadline',date(o.deadline))+'</div>'+orderBudget(o,'food')+orderBudget(o,'delivery')+'<p class="small muted" style="margin-top:14px">'+esc(o.notes)+'</p><div class="note">Food purchase support is intended for '+esc(o.supplier)+'. Transportation support is intended for the agreed delivery provider after quote review. No payment, inventory reservation or purchase order is created.</div>'+(o.itemId?'<div style="margin-top:14px">'+btn('View food listing','food','',o.itemId)+'</div>':'')+'<h3>Order pledges</h3>'+(o.pledges.map(p=>'<div class="allocation"><div><strong>'+esc(p.sponsor)+'</strong><small>Food '+money(p.food)+' · Transportation '+money(p.delivery)+'</small></div><div>'+badge(p.status,p.status==='Confirmed'?'teal':'amber')+(ops()&&p.status==='Pending'&&orderOpen(o)?'<div style="margin-top:6px">'+btn('Confirm demo funding','order-confirm','sm',o.id+'|'+p.id)+'</div>':'')+'</div></div>').join('')||'<p class="muted small">Be the first to support this order.</p>')+(orderOpen(o)&&orderGap(o,'food')+orderGap(o,'delivery')>0?'<hr class="rule">'+btn('Fund the order '+icon('arrow'),'order-pledge','primary full',id):'')+(ops()&&o.status!=='Canceled'?'<hr class="rule">'+btn('Cancel campaign & release demo pledges','order-cancel','danger full',id):''),o.id+' · PURCHASE FUNDING');}
function orderPledgeDialog(id){const o=order(id);if(!orderOpen(o)||orderGap(o,'food')+orderGap(o,'delivery')<=0){orderDetail(id);return;}const choices=orderGap(o,'food')&&orderGap(o,'delivery')?[['food','Food only'],['delivery','Transportation only'],['both','Food + transportation']]:orderGap(o,'food')?[['food','Food only']]:[['delivery','Transportation only']];const mode=choices[0][0];dialog('Fund the order','<h3 style="margin-top:0">'+esc(o.title)+'</h3><p class="muted small">For '+esc(o.buyer)+'</p>'+orderBudget(o,'food')+orderBudget(o,'delivery')+'<h3>Choose what your support covers</h3>'+orderForm('pledge','<div class="purpose-choices">'+choices.map(([v,t])=>'<label><input type="radio" name="purpose" value="'+v+'" '+(mode===v?'checked':'')+'>'+t+'</label>').join('')+'</div>'+field('sponsor','Sponsor / individual / company','text','','required maxlength="80"')+'<div class="form-grid"><div data-funding-food '+(mode==='delivery'?'hidden':'')+'>'+field('food','Food purchase contribution ($)','number',mode==='delivery'?0:Math.min(250,orderGap(o,'food')),'min="0" max="'+orderGap(o,'food')+'" step="0.01" required')+'</div><div data-funding-delivery '+(mode==='food'?'hidden':'')+'>'+field('delivery','Transportation contribution ($)','number',mode==='food'?0:Math.min(100,orderGap(o,'delivery')),'min="0" max="'+orderGap(o,'delivery')+'" step="0.01" required')+'</div></div><button class="btn sm" type="button" data-action="order-fill" data-id="'+id+'">Cover the remaining amount for my selection</button><div class="note blue" style="margin-bottom:14px">The two amounts stay assigned to their selected purposes. This is a pending demo pledge; no payment is collected.</div><label class="check"><input type="checkbox" required> I understand this is a simulated pledge.</label>',id,'Record order pledge'),o.id+' · FOOD + DELIVERY');}
function orderCreateDialog(fid=''){const f=item(fid),existing=f&&state.orders.find(o=>o.itemId===fid&&o.status!=='Canceled');if(existing){orderDetail(existing.id);return;}dialog('Start an order campaign',orderForm('create','<p class="muted small" style="margin-bottom:16px">Raise support for food being purchased by a food bank, community group or individual. Keep the food price and transportation estimate separate.</p><input type="hidden" name="itemId" value="'+esc(f?.id||'')+'"><div class="form-grid">'+field('title','Order / campaign title','text',f?.product||'','required maxlength="100"')+select('buyerType','Purchaser type',['Food bank','Community group / individual'],state.role==='bank'?'Food bank':'Community group / individual')+field('buyer','Purchaser / food bank / community','text',state.role==='bank'?state.bank:'','required maxlength="100"')+field('supplier','Food supplier','text',f?.org||'','required maxlength="100"')+field('quantity','Quantity to purchase','number',f?Math.max(1,Math.min(3,f.pallets-held(f))):1,'required min="1" step="1"'+(f?' max="'+Math.max(0,f.pallets-held(f))+'"':''))+select('unit','Unit',f?['pallets']:['pallets','cases','boxes','orders'],'pallets')+field('unitPrice','Food price per unit ($)','number',f?.price||'','required min="0.01" step="0.01"'+(f?' readonly':''))+field('deliveryTarget','Transportation budget ($)','number',0,'required min="0" step="0.01"')+field('deadline','Funding deadline','date',f?.deadline||'2026-10-30','required min="'+demoDate+'"')+area('notes','Purchase, pickup and delivery details')+'</div><div class="note" style="margin-bottom:14px">Food budget = quantity × unit price. Use $0 for transportation if pickup is arranged. Prices are illustrative and need supplier confirmation.</div>','','Create order campaign'),'FOOD PURCHASE FUNDING',true);}
function fundingLeaders(filter='all'){const rows=new Map();const add=(p,key,food,delivery,general=0)=>{if(p.status!=='Confirmed'||p.sourceGeneral||p.sourceBuyer)return;const name=String(p.sponsor||'Anonymous supporter').trim(),k=name.toLocaleLowerCase(),r=rows.get(k)||{name,food:0,delivery:0,general:0,supported:new Set()};r.food=round(r.food+food);r.delivery=round(r.delivery+delivery);r.general=round(r.general+general);if(key&&((filter==='food'&&food>0)||(filter==='delivery'&&delivery>0)||(filter==='all'&&food+delivery>0)))r.supported.add(key);rows.set(k,r);};state.shipments.filter(s=>s.status!=='Canceled').forEach(s=>s.pledges.forEach(p=>add(p,s.id,0,p.amount)));state.orders.filter(o=>o.status!=='Canceled').forEach(o=>o.pledges.forEach(p=>add(p,o.id,p.food,p.delivery)));state.generalDonations.forEach(p=>add(p,null,0,0,p.amount));return [...rows.values()].map(r=>({...r,total:round(r.food+r.delivery+r.general),score:filter==='food'?r.food:filter==='delivery'?r.delivery:filter==='general'?r.general:round(r.food+r.delivery+r.general),count:r.supported.size})).filter(r=>r.score>0).sort((a,b)=>b.score-a.score||a.name.localeCompare(b.name));}
function milestone(amount){const goals=[500,1000,2500,5000,10000,25000,50000,100000],next=goals.find(g=>g>amount)||Math.ceil((amount+1)/100000)*100000,earned=[...goals].reverse().find(g=>amount>=g)||0;return{next,earned,progress:Math.min(100,amount/next*100)};}
function leaderboardPanel(){const rows=fundingLeaders(leaderboardView),total=rows.reduce((n,r)=>n+r.score,0),all=fundingLeaders('all');return '<section class="leaderboard-section" id="funding-leaderboard"><div class="leaderboard-heading"><div><div class="eyebrow">A little friendly competition. More food on the table.</div><h2>Funding leaderboard</h2><p>Recognizing the people and organizations funding food, transportation, and the general fund.</p></div>'+'<div class="row wrap">'+btn('DONATE','donate','primary')+btn('Fund an order '+icon('arrow'),'quick','','order')+'</div>'+'</div><div class="leaderboard-summary"><div><strong>'+money(total)+'</strong><span>confirmed '+(leaderboardView==='food'?'food purchase':leaderboardView==='delivery'?'transportation':leaderboardView==='general'?'general fund':'network')+' support</span></div><div><strong>'+rows.length+'</strong><span>supporters in this view</span></div><div><strong>'+new Set(all.flatMap(r=>[...r.supported])).size+'</strong><span>orders and deliveries supported overall</span></div></div><div class="leaderboard-controls"><div class="tabs" role="group" aria-label="Leaderboard funding category">'+[['all','All funding'],['food','Food purchases'],['delivery','Transportation'],['general','General support']].map(([v,t])=>'<button class="tab '+(leaderboardView===v?'active':'')+'" data-action="leaderboard-view" data-id="'+v+'" aria-pressed="'+(leaderboardView===v)+'">'+t+'</button>').join('')+'</div><span class="demo-tag">All-time demo ranking</span></div><div class="card table-wrap"><table class="leaderboard-table"><thead><tr><th>Rank / supporter</th><th>Confirmed support</th><th>Funding mix</th><th>Supported</th><th>Next milestone</th></tr></thead><tbody>'+rows.map((r,i)=>{const m=milestone(r.score),rank=1+rows.filter(x=>x.score>r.score).length;return '<tr><td><div class="leader-name"><span class="rank rank-'+rank+'">'+rank+'</span><div><strong>'+esc(r.name)+'</strong><small>'+(rank===1?'Leading the way':m.earned?money(m.earned)+' milestone reached':'First contribution counted')+'</small></div></div></td><td><strong class="leader-amount">'+money(r.score)+'</strong><small>confirmed '+(leaderboardView==='all'?'total':leaderboardView==='food'?'food support':leaderboardView==='general'?'general support':'transportation support')+'</small></td><td>'+money(r.food)+' food<small>'+money(r.delivery)+' transportation</small>'+(r.general?'<small>'+money(r.general)+' general fund</small>':'')+'</td><td>'+(r.count?r.count+' '+(leaderboardView==='food'?(r.count===1?'order':'orders'):leaderboardView==='delivery'?(r.count===1?'delivery':'deliveries'):(r.count===1?'order / delivery':'orders / deliveries')):'General fund')+'</td><td><div class="milestone-label"><strong>'+money(m.next)+'</strong><small>'+money(round(m.next-r.score))+' to go</small></div><div class="progress milestone-progress"><span style="width:'+m.progress+'%"></span></div></td></tr>';}).join('')+'</tbody></table>'+(rows.length?'':'<div class="empty">No confirmed support in this category yet. Be the first to help.</div>')+'</div><div class="note">Rankings use confirmed demo funding, including support for orders and deliveries still in progress. Pending pledges and canceled campaigns are excluded. Matching contributions count once under the matching sponsor. General donations count once when confirmed. Their later allocation is never counted as a second contribution. Dollar milestones apply to the selected category; completed food delivery is reported separately below.</div></section>';}
function impactPage(){return head('','Impact & community champions','See who is funding the network, then follow the food through completed deliveries.')+leaderboardPanel()+'<div class="completed-impact">'+deliveredImpactPage().replace('<h1>Good intentions. Confirmed impact.</h1>','<h2>Completed delivery impact</h2>')+'</div>';}
document.addEventListener('change',e=>{if(e.target.name!=='purpose'||!e.target.closest('[data-funding-form="pledge"]'))return;const f=e.target.closest('form'),mode=e.target.value,food=f.querySelector('[name="food"]'),delivery=f.querySelector('[name="delivery"]');f.querySelector('[data-funding-food]').hidden=mode==='delivery';f.querySelector('[data-funding-delivery]').hidden=mode==='food';if(mode==='delivery')food.value=0;if(mode==='food')delivery.value=0;});
document.addEventListener('click',e=>{const n=e.target.closest('[data-action]');if(!n)return;const a=n.dataset.action,id=n.dataset.id;try{if(a==='funding-view'){fundingView=id;render();}if(a==='leaderboard-view'){leaderboardView=id;render();}if(a==='order-create')orderCreateDialog();if(a==='order-from-food')orderCreateDialog(id);if(a==='order-detail')orderDetail(id);if(a==='order-pledge')orderPledgeDialog(id);if(a==='order-fill'){const f=n.closest('form'),mode=f.querySelector('[name="purpose"]:checked').value,o=order(id);f.querySelector('[name="food"]').value=mode==='delivery'?0:orderGap(o,'food');f.querySelector('[name="delivery"]').value=mode==='food'?0:orderGap(o,'delivery');}if(a==='order-confirm'){const [oid,pid]=id.split('|');confirmOrderPledge(oid,pid);notify(oid+': order funding confirmed.');save();render();orderDetail(oid);}if(a==='order-cancel'&&ops())dialog('Cancel this order campaign?',orderForm('cancel','<p>Release all pledges from this demonstration campaign. This simulates reconciliation and does not move money.</p><label class="check"><input type="checkbox" required> I have reviewed the demo cancellation and release.</label>',id,'Cancel and release demo pledges'),id,true);}catch(error){toast(error.message);}});
document.addEventListener('submit',e=>{const el=e.target;if(!el.dataset.fundingForm)return;e.preventDefault();const values=Object.fromEntries(new FormData(el)),kind=el.dataset.fundingForm;try{if(kind==='pledge'){if(!['food','delivery','both'].includes(values.purpose))throw Error('Choose a funding purpose.');const food=values.purpose==='delivery'?0:values.food,delivery=values.purpose==='food'?0:values.delivery;if(values.purpose==='both'&&(!(Number(food)>0)||!(Number(delivery)>0)))throw Error('Enter an amount for both food and transportation, or select one purpose.');addOrderPledge(el.dataset.id,values.sponsor,food,delivery);notify(el.dataset.id+': new food/order funding pledge from '+values.sponsor);save();render();orderDetail(el.dataset.id);toast('Order pledge recorded. Funding is pending confirmation.');}if(kind==='create'){const o=createPurchaseOrder(values);notify(o.id+': new food purchase campaign.');save();fundingView='orders';page='sponsor';render();orderDetail(o.id);}if(kind==='cancel'){if(!ops())throw Error('Operations access is required.');const o=order(el.dataset.id);if(o.deliveryShipmentId&&['In transit','Delivered'].includes(ship(o.deliveryShipmentId)?.status))throw Error('This order is committed to a released delivery. Review it with operations.');o.status='Canceled';if(o.deliveryShipmentId&&ship(o.deliveryShipmentId))ship(o.deliveryShipmentId).review='Linked food order canceled; reconcile the delivery.';o.pledges.forEach(p=>p.status='Released');save();render();orderDetail(o.id);toast('Campaign canceled and demo pledges released.');}}catch(error){el.querySelector('.error').textContent=error.message;}});
const generalTotal=status=>round(state.generalDonations.filter(p=>p.status===status).reduce((n,p)=>n+p.amount,0));
function addGeneralDonation(sponsor,amount){
 sponsor=String(sponsor||'').trim();amount=round(Number(amount));
 if(!sponsor)throw Error('Enter your name or organization.');
 if(!Number.isFinite(amount)||amount<=0||amount>1000000)throw Error('Choose an amount from $0.01 to $1,000,000.');
 const pledge={id:uid('G-'),sponsor:sponsor.slice(0,80),amount,status:'Pending',date:demoDate};
 state.generalDonations.unshift(pledge);return pledge;
}
function confirmGeneralDonation(id){
 if(!ops())throw Error('Switch to BHD Operations to confirm funding.');
 const p=state.generalDonations.find(p=>p.id===id);
 if(!p||p.status!=='Pending')throw Error('This donation is no longer pending.');
 p.status='Confirmed';
}
function releaseGeneralDonation(id){
 if(!ops())throw Error('Switch to BHD Operations to release a pending pledge.');
 const p=state.generalDonations.find(p=>p.id===id);
 if(!p||p.status!=='Pending')throw Error('Only pending pledges can be released here.');
 p.status='Released';
}
function generalDonationPage(){
 return head('','Give where it’s needed most.','Support the whole network without choosing a particular order, food bank, or delivery.')+
 '<div class="general-layout"><section class="card general-giving"><div class="general-intro">'+icon('heart')+'<div><h2>General donation</h2><p>Flexible support for food purchases and transportation across the network.</p></div></div>'+orderForm('general',
 '<div class="donation-label">Choose a one-time amount</div><div class="donation-amounts" role="group" aria-label="Suggested donation amounts">'+[25,50,100,250,500].map(n=>'<button class="btn" type="button" data-action="general-amount" data-id="'+n+'">'+money(n)+'</button>').join('')+'</div>'+
 field('general-amount','Donation amount ($)','number',100,'required min="0.01" max="1000000" step="0.01"')+
 field('general-sponsor','Your name or organization','text','','required maxlength="80" placeholder="Name shown on the funding leaderboard"')+
 '<div class="note blue">General support goes into one unallocated fund. Operations can decide which network needs to support later. No specific order or delivery is selected.</div><div class="note">Demo only: this records a pledge. No money is collected, recurring charge started, or tax receipt issued.</div><label class="check"><input type="checkbox" required> I understand this is a simulated donation.</label>', '', 'Record general donation')+'</section>'+
 '<aside class="card general-overview"><div class="eyebrow">GENERAL FUND · DEMO</div><h2>Ready for the next need</h2><div class="general-balance"><strong>'+money(generalAvailable())+'</strong><span>confirmed, available to allocate</span></div><div class="quote-line"><span>Pending confirmation</span><strong>'+money(generalTotal('Pending'))+'</strong></div><p>Confirmed general donations appear on the funding leaderboard. Allocations reduce the receiving campaign’s funding gap. Impact counts delivered food only.</p>'+btn('View funding leaderboard '+icon('arrow'),'quick','ghost','impact')+'<div class="note">Operations records each allocation against a specific food order or delivery. Explore the allocation trail below.</div></aside></div>'+
 '<div class="section-head general-ledger-heading"><h2>General donation ledger</h2><span class="small muted">'+(ops()?'Confirm or release pending demo pledges':'Operations confirms pending demo pledges')+'</span></div><div class="card table-wrap"><table><thead><tr><th>Supporter</th><th>Amount</th><th>Status</th><th>Use of funds</th><th>Action</th></tr></thead><tbody>'+state.generalDonations.map(p=>'<tr><td><strong>'+esc(p.sponsor)+'</strong><small>'+esc(p.id)+' · '+date(p.date)+'</small></td><td>'+money(p.amount)+'</td><td>'+badge(p.status,p.status==='Confirmed'?'teal':p.status==='Pending'?'amber':'gray')+'</td><td>'+(p.status==='Released'?'Pledge released':p.status==='Pending'?'Awaiting confirmation':money(generalDonationAvailable(p.id))+' available · '+money(p.amount-generalDonationAvailable(p.id))+' allocated')+'</td><td>'+(ops()&&p.status==='Pending'?'<div class="row wrap">'+btn('Confirm demo donation','general-confirm','sm',p.id)+btn('Release pledge','general-release','sm',p.id)+'</div>':'—')+'</td></tr>').join('')+'</tbody></table>'+(state.generalDonations.length?'':'<div class="empty">Be the first to support the general fund.</div>')+'</div>';
}
document.addEventListener('click',e=>{
 const n=e.target.closest('[data-action]');if(!n)return;
 try{
  if(n.dataset.action==='donate'){fundingView='general';go('sponsor');}
  if(n.dataset.action==='general-amount'){n.closest('form').querySelector('[name="general-amount"]').value=n.dataset.id;}
  if(n.dataset.action==='general-confirm'){confirmGeneralDonation(n.dataset.id);notify('General donation confirmed.');render();toast('General support confirmed and added to the leaderboard.');}
  if(n.dataset.action==='general-release'){releaseGeneralDonation(n.dataset.id);save();render();toast('Pending demo pledge released.');}
 }catch(error){toast(error.message);}
});
document.addEventListener('submit',e=>{
 const el=e.target;if(el.dataset.fundingForm!=='general')return;e.preventDefault();
 const values=Object.fromEntries(new FormData(el));
 try{addGeneralDonation(values['general-sponsor'],values['general-amount']);notify('New general donation pledge recorded.');render();toast('Thank you! Your general donation is pending confirmation. No money was collected.');}
 catch(error){el.querySelector('.error').textContent=error.message;}
});
